// Custom Button - E11 Anti-AI Pattern
import { designTokens } from '../design-system/tokens';

interface ButtonProps {
  variant: 'primary' | 'secondary' | 'ghost';
  size: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

export function Button({ variant, size, children, ...props }: ButtonProps) {
  // Custom styling, not generic shadcn presets
  const baseStyles = 'font-medium transition-all duration-200 rounded-lg';

  const variants = {
    primary: `bg-brand-500 hover:bg-brand-600 text-white shadow-soft hover:shadow-medium`,
    secondary: `bg-brand-50 hover:bg-brand-100 text-brand-900 border border-brand-200`,
    ghost: `hover:bg-brand-50 text-brand-700`
  };

  const sizes = {
    sm: `px-3 py-1.5 text-sm`,
    md: `px-4 py-2 text-base`,
    lg: `px-6 py-3 text-lg`
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]}`}
      {...props}
    >
      {children}
    </button>
  );
}

