// E16 Runtime Validation Guards
import { z } from 'zod';

// Environment validation (E10)
export const envSchema = z.object({
  NODE_ENV: z.enum(['development', 'production', 'test']),
  DATABASE_URL: z.string().url(),
  API_KEY: z.string().min(10),
  // No default values - force explicit config
});

// API input validation guards
export const createUserSchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  age: z.number().int().min(13).max(120) // Business rules
});

// Deployment config validation
export const deployConfigSchema = z.object({
  region: z.enum(['us-east-1', 'eu-west-1']),
  environment: z.enum(['staging', 'production']),
  replicas: z.number().int().min(1).max(10),
  // Prevent accidental wrong deployments
});

// Validate on app boot
export function validateEnvironment() {
  try {
    envSchema.parse(process.env);
    console.log('✅ Environment validation passed');
  } catch (error) {
    console.error('❌ Environment validation failed:', error);
    process.exit(1);
  }
}
